class CoCoMEOrderProducts_AutoGenerated {
  /*SystemVariable Start*/
  CurrentCashDesk: CashDesk;
  CurrentStore: Store;
  /*SystemVariable End*/

  /*find an item with the provided barcode,
   *if the item is not exist,
   *create an order entry,
   *and the set the quantity to the provided quantity,
   *and the subamount is the item price multiply the quantity and the order item is the item,
   *and save the order entry and the current order product is contain the order entry*/
  orderItem(barcode: number, quantity: number): boolean {
    /*Definition Start*/
    let item: Item = l({
      logic: () =>
        getRepository(Item).find(
          (i: any) =>
            l({
              logic: () => i.Barcode === barcode,
              description: "i.Barcode=barcode",
            }).build().pass,
        ),
      description: "Item.allInstance()->any(i|i.Barcode=barcode)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(item) === false,
        description: "item.oclIsUndefined()=false",
      })
        .and({
          logic: () =>
            StandardOPs.oclIsUndefined(this.CurrentOrderProduct) === false,
          description: "self.CurrentOrderProduct.oclIsUndefined()=false",
        })
        .and({
          logic: () => quantity > 0,
          description: "quantity>0",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let oe: OrderEntry;
    return l({
      execute: () => (oe = new OrderEntry()),
      description: "oe.oclIsNew()",
    })
      .and({
        execute: () => getRepository(OrderEntry).push(oe),
        description: "OrderEntry.allInstance()->includes(oe)",
      })
      .and({
        execute: () => (oe.Quantity = quantity),
        description: "oe.Quantity=quantity",
      })
      .and({
        execute: () => (oe.SubAmount = item.Price * quantity),
        description: "oe.SubAmount=item.Price*quantity",
      })
      .and({
        execute: () => (oe.Item = item),
        description: "oe.Item=item",
      })
      .and({
        execute: () => this.CurrentOrderProduct.ContainedEntries.push(oe),
        description: "self.CurrentOrderProduct.ContainedEntries->includes(oe)",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}

